public boolean canArrange(int[] arr, int k) {
    if (arr == null || arr.length % 2 != 0) {
        return false;
    }
    if (k <= 0) {
        return false; // or throw exception
    }
    int[] count = new int[k];
    for (int value : arr) {
        int rem = ((value % k) + k) % k; // handle negative values
        count[rem]++;
    }
    // Remainder 0 elements must pair among themselves
    if (count[0] % 2 != 0) {
        return false;
    }
    // If k is even, remainder k/2 elements must pair among themselves
    if (k % 2 == 0) {
        if (count[k / 2] % 2 != 0) {
            return false;
        }
    }
    // For all other remainders, counts must match their complement
    for (int r = 1; r <= k / 2; r++) {
        if (r == k - r) { // already handled for even k above
            continue;
        }
        if (count[r] != count[k - r]) {
            return false;
        }
    }
    return true;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    // Build adjacency list for the tree
    java.util.List<Integer>[] graph = new java.util.ArrayList[n];
    for (int i = 0; i < n; i++) {
        graph[i] = new java.util.ArrayList<>();
    }
    for (int[] e : edges) {
        int u = e[0], v = e[1];
        graph[u].add(v);
        graph[v].add(u);
    }

    // Parent array to avoid revisiting parent node
    int[] parent = new int[n];
    java.util.Arrays.fill(parent, -1);
    parent[0] = -2;

    // Perform DFS to get traversal order
    java.util.Stack<Integer> stack = new java.util.Stack<>();
    stack.push(0);
    java.util.List<Integer> order = new java.util.ArrayList<>();
    while (!stack.isEmpty()) {
        int u = stack.pop();
        order.add(u);
        for (int v : graph[u]) {
            if (v == parent[u]) continue;
            parent[v] = u;
            stack.push(v);
        }
    }

    // Process nodes in reverse order to accumulate apple counts and calculate time
    int total = 0;
    int[] appleCount = new int[n];
    for (int i = order.size() - 1; i >= 0; i--) {
        int u = order.get(i);
        appleCount[u] = hasApple[u] ? 1 : 0;
        for (int v : graph[u]) {
            if (parent[v] == u) { // v is a child of u
                if (appleCount[v] > 0) {
                    total += 2;          // go to child and return
                    appleCount[u] += appleCount[v];
                }
            }
        }
    }
    return total;
}

public String sortString(String s) {
    if (s == null || s.isEmpty()) {
        return "";
    }
    // Count occurrences of each character (assuming ASCII)
    int[] count = new int[256];
    for (int i = 0; i < s.length(); i++) {
        count[s.charAt(i)]++;
    }

    StringBuilder result = new StringBuilder();
    int remaining = s.length();

    while (remaining > 0) {
        // Ascending phase
        int prev = -1; // last appended character code
        while (true) {
            int next = -1;
            for (int c = prev + 1; c < 256; c++) {
                if (count[c] > 0) {
                    next = c;
                    break;
                }
            }
            if (next == -1) {
                break; // no larger character left
            }
            result.append((char) next);
            count[next]--;
            prev = next;
            remaining--;
        }

        if (remaining == 0) {
            break;
        }

        // Descending phase
        int prevDesc = 256; // start from beyond maximum character
        while (true) {
            int next = -1;
            for (int c = prevDesc - 1; c >= 0; c--) {
                if (count[c] > 0) {
                    next = c;
                    break;
                }
            }
            if (next == -1) {
                break; // no smaller character left
            }
            result.append((char) next);
            count[next]--;
            prevDesc = next;
            remaining--;
        }
    }

    return result.toString();
}

public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n <= 1) return false;
    int total = 0;
    for (int num : nums) total += num;
    @SuppressWarnings("unchecked")
    java.util.HashSet<Integer>[] subsets = new java.util.HashSet[n + 1];
    for (int i = 0; i <= n; i++) subsets[i] = new java.util.HashSet<>();
    subsets[0].add(0);
    for (int num : nums) {
        for (int sz = n - 1; sz >= 0; sz--) {
            for (int sumVal : subsets[sz]) {
                subsets[sz + 1].add(sumVal + num);
            }
        }
    }
    for (int k = 1; k <= n / 2; k++) {
        if ((total * k) % n != 0) continue;
        int target = (total * k) / n;
        if (subsets[k].contains(target)) return true;
    }
    return false;
}

public int minCostClimbingStairs(int[] cost) {
    int n = cost.length;
    int prev2 = 0; // dp[i-2]
    int prev1 = 0; // dp[i-1]
    for (int i = 2; i <= n; i++) {
        int fromPrev1 = prev1 + cost[i - 1];
        int fromPrev2 = prev2 + cost[i - 2];
        int curr = Math.min(fromPrev1, fromPrev2);
        prev2 = prev1;
        prev1 = curr;
    }
    return prev1;
}

