public int maxAbsoluteSum(int[] nums) {
    if (nums == null || nums.length == 0) {
        return 0;
    }

    int maxEndingHere = nums[0];
    int maxSoFar = nums[0];
    int minEndingHere = nums[0];
    int minSoFar = nums[0];

    for (int i = 1; i < nums.length; i++) {
        int val = nums[i];

        // For maximum subarray sum
        maxEndingHere = Math.max(val, maxEndingHere + val);
        maxSoFar = Math.max(maxSoFar, maxEndingHere);

        // For minimum subarray sum
        minEndingHere = Math.min(val, minEndingHere + val);
        minSoFar = Math.min(minSoFar, minEndingHere);
    }

    return Math.max(Math.abs(maxSoFar), Math.abs(minSoFar));
}

public int findMinFibonacciNumbers(int k) {
    // Generate Fibonacci numbers up to k
    int[] fib = new int[50]; // array large enough for k up to 10^9
    int len = 0;
    fib[len++] = 1;
    fib[len++] = 1;
    while (true) {
        int next = fib[len - 1] + fib[len - 2];
        if (next > k) break;
        fib[len++] = next;
    }

    int count = 0;
    int remaining = k;
    int idx = len - 1;

    // Greedy: subtract the largest Fibonacci number not exceeding remaining
    while (remaining > 0) {
        while (fib[idx] > remaining) {
            idx--;
        }
        remaining -= fib[idx];
        count++;
    }

    return count;
}

public int kthFactor(int n, int k) {
    List<Integer> small = new ArrayList<>();
    List<Integer> large = new ArrayList<>();
    for (int i = 1; (long)i * i <= n; i++) {
        if (n % i == 0) {
            small.add(i);
            int other = n / i;
            if (other != i) {
                large.add(other);
            }
        }
    }
    int smallCount = small.size();
    if (k <= smallCount) {
        return small.get(k - 1);
    }
    int idxLarge = k - smallCount - 1;
    if (idxLarge < large.size()) {
        return large.get(large.size() - 1 - idxLarge);
    }
    return -1;
}

