public int minOperations(String[] logs) {
    int depth = 0;
    for (String log : logs) {
        if ("./".equals(log)) {
            // Stay in the current directory; no change in depth.
            continue;
        } else if ("../".equals(log)) {
            // Move up one directory if possible.
            if (depth > 0) {
                depth--;
            }
        } else {
            // Enter a new subdirectory.
            depth++;
        }
    }
    // The remaining depth is the number of steps needed to return to the main folder.
    return depth;
}

