public static int singleNumber(int[] nums) {
    int ones = 0, twos = 0;
    for (int num : nums) {
        // Update twos first: numbers which have appeared second time
        twos |= ones & num;
        // Update ones: toggle bits of current num
        ones ^= num;
        // Mask to remove bits that have appeared three times
        int commonMask = ~(ones & twos);
        ones &= commonMask;
        twos &= commonMask;
    }
    return ones;
}

public static List<Integer> findSteppingNumbers(int low, int high) {
    List<Integer> result = new java.util.ArrayList<>();
    if (low <= 0 && high >= 0) {
        result.add(0);
    }
    java.util.Queue<Long> queue = new java.util.LinkedList<>();
    for (int d = 1; d <= 9; d++) {
        queue.offer((long)d);
    }
    while (!queue.isEmpty()) {
        long num = queue.poll();
        if (num > high) {
            continue;
        }
        if (num >= low) {
            result.add((int)num);
        }
        long lastDigit = num % 10;
        if (num > high / 10) {
            continue; // children would definitely exceed high
        }
        if (lastDigit > 0) {
            long child = num * 10 + (lastDigit - 1);
            if (child <= high) {
                queue.offer(child);
            }
        }
        if (lastDigit < 9) {
            long child = num * 10 + (lastDigit + 1);
            if (child <= high) {
                queue.offer(child);
            }
        }
    }
    return result;
}

public static int countDigitOne(int n) {
    if (n <= 0) return 0;
    long count = 0;
    long N = n;
    for (long factor = 1; factor <= N; factor *= 10) {
        long lower = N % factor;
        long current = (N / factor) % 10;
        long higher = N / (factor * 10);
        if (current == 0) {
            count += higher * factor;
        } else if (current == 1) {
            count += higher * factor + lower + 1;
        } else {
            count += (higher + 1) * factor;
        }
    }
    return (int) count;
}

