    int count = 0;
    for (int i = s.length() - 1; i >= 0; i--) {
        sb.append(s.charAt(i));
        count++;
        if (count % 3 == 0 && i != 0) {
            sb.append('.');
        }
    }
    if (negative) {
        sb.append('-');
    }
    return sb.reverse().toString();
}

public static int squarePermutations(int[] A) {
    int n = A.length;
    if (n == 0) return 0;
    int fullMask = (1 << n) - 1;

    // Precompute adjacency: whether sum of A[i] and A[j] is a perfect square
    boolean[][] can = new boolean[n][n];
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            if (i == j) continue;
            int sum = A[i] + A[j];
            int root = (int) Math.sqrt(sum);
            can[i][j] = (root * root == sum);
        }
    }

    int[][] dp = new int[1 << n][n];
    for (int i = 0; i < n; i++) {
        dp[1 << i][i] = 1;
    }

    for (int mask = 1; mask <= fullMask; mask++) {
        for (int last = 0; last < n; last++) {
            if ((mask & (1 << last)) == 0) continue;
            int cur = dp[mask][last];
            if (cur == 0) continue;
            for (int next = 0; next < n; next++) {
                if ((mask & (1 << next)) != 0) continue;
                if (can[last][next]) {
                    dp[mask | (1 << next)][next] += cur;
                }
            }
        }
    }

    int result = 0;
    for (int i = 0; i < n; i++) {
        result += dp[fullMask][i];
    }
    return result;
}

public static int largestRectangleArea(int[] heights) {
    int n = heights.length;
    java.util.Stack<Integer> stack = new java.util.Stack<>();
    int maxArea = 0;
    for (int i = 0; i <= n; i++) {
        int currentHeight = (i == n) ? 0 : heights[i];
        while (!stack.isEmpty() && currentHeight < heights[stack.peek()]) {
            int height = heights[stack.pop()];
            int leftBoundary = stack.isEmpty() ? 0 : stack.peek() + 1;
            int width = i - leftBoundary;
            long area = (long) height * width;
            if (area > maxArea) {
                maxArea = (int) area;
            }
        }
        stack.push(i);
    }
    return maxArea;
}

public static int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0) {
        return new int[0];
    }
    int m = mat.length;
    int n = mat[0].length;
    int[] result = new int[m * n];
    int index = 0;
    for (int d = 0; d < m + n - 1; d++) {
        int r = Math.min(d, m - 1);
        int c = d - r;
        if (d % 2 == 0) {
            while (r >= 0 && c < n) {
                result[index++] = mat[r][c];
                r--;
                c++;
            }
        } else {
            while (c >= 0 && r < m) {
                result[index++] = mat[r][c];
                r++;
                c--;
            }
        }
    }
    return result;
}

public static int findSmallestInteger(int n) {
    char[] digits = Integer.toString(n).toCharArray();
    int i = digits.length - 2;
    while (i >= 0 && digits[i] >= digits[i + 1]) {
        i--;
    }
    if (i < 0) {
        return -1; // no larger permutation
    }
    int j = digits.length - 1;
    while (digits[j] <= digits[i]) {
        j--;
    }
    // swap digits[i] and digits[j]
    char temp = digits[i];
    digits[i] = digits[j];
    digits[j] = temp;
    // reverse the suffix starting at i+1
    int left = i + 1;
    int right = digits.length - 1;
    while (left < right) {
        temp = digits[left];
        digits[left] = digits[right];
        digits[right] = temp;
        left++;
        right--;
    }
    try {
        int result = Integer.parseInt(new String(digits));
        return result > n ? result : -1;
    } catch (NumberFormatException e) {
        return -1;
    }
}

