}

public static boolean isBoomerang(int[][] points) {
    if (points == null || points.length != 3) {
        return false;
    }
    int x1 = points[0][0], y1 = points[0][1];
    int x2 = points[1][0], y2 = points[1][1];
    int x3 = points[2][0], y3 = points[2][1];

    // Check that all points are distinct
    if ((x1 == x2 && y1 == y2) || (x1 == x3 && y1 == y3) || (x2 == x3 && y2 == y3)) {
        return false;
    }

    // Check for non-collinearity using the area of the triangle
    long area = (long) (x2 - x1) * (y3 - y1) - (long) (x3 - x1) * (y2 - y1);
    return area != 0;
}

public static int findNthUglyNumber(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("Input must be a positive integer.");
    }
    int[] ugly = new int[n];
    ugly[0] = 1;
    int i2 = 0, i3 = 0, i5 = 0;
    int nextMultOf2 = 2;
    int nextMultOf3 = 3;
    int nextMultOf5 = 5;

    for (int i = 1; i < n; i++) {
        int nextUgly = Math.min(nextMultOf2, Math.min(nextMultOf3, nextMultOf5));
        ugly[i] = nextUgly;
        if (nextUgly == nextMultOf2) {
            i2++;
            nextMultOf2 = ugly[i2] * 2;
        }
        if (nextUgly == nextMultOf3) {
            i3++;
            nextMultOf3 = ugly[i3] * 3;
        }
        if (nextUgly == nextMultOf5) {
            i5++;
            nextMultOf5 = ugly[i5] * 5;
        }
    }
    return ugly[n - 1];
}

public static int calculateEnergy(String s) {
    if (s == null || s.isEmpty()) {
        return 0;
    }
    int max = 1;
    int current = 1;
    for (int i = 1; i < s.length(); i++) {
        if (s.charAt(i) == s.charAt(i - 1)) {
            current++;
            if (current > max) {
                max = current;
            }
        } else {
            current = 1;
        }
    }
    return max;
}

