public static int calculateUniqueSum(int[] nums) {
    if (nums == null || nums.length == 0) {
        return 0;
    }
    java.util.HashMap<Integer, Integer> freq = new java.util.HashMap<>();
    for (int num : nums) {
        freq.merge(num, 1, Integer::sum);
    }
    int sum = 0;
    for (java.util.Map.Entry<Integer, Integer> entry : freq.entrySet()) {
        if (entry.getValue() == 1) {
            sum += entry.getKey();
        }
    }
    return sum;
}

public static int minPerfectSquareSum(int n) {
    if (n <= 0) return 0;
    if (isPerfectSquare(n)) return 1;
    for (int i = 1; i * i <= n; i++) {
        int remainder = n - i * i;
        if (isPerfectSquare(remainder)) return 2;
    }
    int temp = n;
    while (temp % 4 == 0) {
        temp /= 4;
    }
    if (temp % 8 == 7) return 4;
    return 3;
}

public static String reverseWords(String s) {
    if (s == null) {
        return null;
    }
    StringBuilder result = new StringBuilder();
    StringBuilder word = new StringBuilder();
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == ' ') {
            result.append(word.reverse());
            word.setLength(0);
            result.append(c);
        } else {
            word.append(c);
        }
    }
    result.append(word.reverse());
    return result.toString();
}
